import{z as s,x as d,o as B,c as i,q as t,j as r,D as e,d as l,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Leland 动态资本结构","description":"","frontmatter":{"title":"Leland 动态资本结构","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/leland-model.md","filePath":"econ/leland-model.md","lastUpdated":1791413859000}'),p={name:"econ/leland-model.md"};function m(D,a,h,C,c,V){const n=d("Mermaid");return B(),i("div",null,[a[2]||(a[2]=t('<h1 id="leland-动态资本结构" tabindex="-1">Leland 动态资本结构 <a class="header-anchor" href="#leland-动态资本结构" aria-label="Permalink to &quot;Leland 动态资本结构&quot;">​</a></h1><div class="epigraph"><p>把企业资产写成扩散，违约写成内生边界，税盾与破产成本的权衡就变成期权定价：股权是资产的看涨，最优杠杆与最优违约点一起解出。</p><footer>—— Leland, Corporate Debt Value, Bond Covenants, and Optimal Capital Structure, Journal of Finance 1994</footer></div><p><a href="/econ/country-risk-premium">上一课</a>收束了项目贴现。主干上的<a href="/econ/tradeoff-capital">权衡</a>给出静态 \\(V_L=V_U+\\mathrm{PV}(\\text{税盾})-\\mathrm{PV}(\\text{困境})\\)，但债务是一次给定的面值。本课缺口是 Leland（1994）：资产 \\(V\\) 连续变动，股东选择何时把看涨期权交出，税盾与破产成本在同一或有要求权里定价。不重做 Kraus–Litzenberger 的状态表，不把资本预算的 WACC 再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态权衡的 \\(D^\\ast\\) 不回答：资产跌了以后，是立即违约、再注资，还是继续付息？Merton（1974）已把股权写成资产看涨、违约边界等于面值（零息债到期）。Leland 换成永久债（或指数化票息）、违约边界由股东内生选择：当注资付息的边际成本高于维持期权的价值，放弃。缺口是把权衡从「选一个 \\(D\\)」升级为「选票息与违约政策」，使杠杆随 \\(V\\) 内生变动。</p><p><span class="marginnote">直觉类比（有限责任）：股权像一张看涨期权——最坏是本金归零，不会倒欠。资产越跌，这张期权越不值钱，但股东可能仍愿意付息赌反弹；一旦每期「赌资」（利息）比期权本身还贵，就撒手违约。</span></p><p><span class="marginnote">内生违约：有限责任下股东的平滑粘贴（smooth-pasting）决定边界 \\(V_B\\)。外生边界（契约、流动性）会改变债值与最优票息。后课展期与契约会把外生约束加回来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资产 \\(V\\) 服从带漂移的几何布朗。无杠杆价值按 \\(r_U\\) 或风险中性下的资产回报来。杠杆企业：股权 \\(E(V)\\) 满足常微分方程，在 \\(V_B\\) 处为零，平滑粘贴决定 \\(V_B\\)；债务价值 = 承诺票息的现值 − 违约时损失。税盾在 \\(V\\gt V_B\\) 时流入，破产成本在 \\(V_B\\) 按 \\(\\alpha V_B\\) 损耗。最优票息最大化 \\(E+D=V_U+\\mathrm{PV}(\\text{税盾})-\\mathrm{PV}(\\text{破产})\\)。</p><p>比较静态：破产成本 \\(\\alpha\\) 上升、税率下降，最优杠杆下降；波动上升既提高税盾的期权价值也提高违约概率，净效应要拆。这与静态「波动高则债少」同方向，但定量来自期权，不是来自一个外生违约概率。</p><p><span class="marginnote">数字实例：违约点 \\(V_B=60\\)、破产损耗 \\(\\alpha=0.2\\) 时，清算后债权人只拿到 \\(0.8\\times 60=48\\)，剩下的 12 在重整中蒸发。信用利差定价的就是这段蒸发——\\(\\alpha\\) 越大，同样的票息要补的利差越宽。</span></p>',11)),(B(),r(A,null,{default:e(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%B5%84%E4%BA%A7%E6%89%A9%E6%95%A3%20V%22%5D%20--%3E%20E%5B%22%E8%82%A1%E6%9D%83%20%3D%20%E7%9C%8B%E6%B6%A8%22%5D%0A%20%20V%20--%3E%20VB%5B%22%E5%86%85%E7%94%9F%E8%BF%9D%E7%BA%A6%20VB%22%5D%0A%20%20E%20--%3E%20PASTE%5B%22%E5%B9%B3%E6%BB%91%E7%B2%98%E8%B4%B4%22%5D%0A%20%20PASTE%20--%3E%20VB%0A%20%20TAX%5B%22%E7%A8%8E%E7%9B%BE%22%5D%20--%3E%20OPT%5B%22%E6%9C%80%E4%BC%98%E7%A5%A8%E6%81%AF%22%5D%0A%20%20ALPHA%5B%22%E7%A0%B4%E4%BA%A7%E6%8D%9F%E8%80%97%20%CE%B1%22%5D%20--%3E%20OPT%0A%20%20VB%20--%3E%20OPT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 APV：Leland 是连续时间、内生杠杆路径的 APV。资本预算若假设常数 \\(D/V\\)，对应的是 Goldstein–Ju–Leland 一类再平衡扩展，不是 1994 年一次性永久债。本课先钉一次性债的内生违约。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是有限责任加连续交易的期权。股东付息等于买继续赌的权利；边界上，再付一单位的成本等于期权增量。债权人在边界上接手 \\((1-\\alpha)V_B\\)。税盾是政府在存活路径上的转移，家庭仍不能自制，故切片有关——与 MM 1963 同一块摩擦，只是动态化。",-1)),(B(),r(A,null,{default:e(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOWN%5B%22%E8%B5%84%E4%BA%A7%20V%20%E4%B8%8B%E8%A1%8C%EF%BC%8C%E9%80%BC%E8%BF%91%E8%BE%B9%E7%95%8C%22%5D%20--%3E%20Q%7B%22%E8%82%A1%E4%B8%9C%EF%BC%9A%E7%BB%A7%E7%BB%AD%E4%BB%98%E6%81%AF%E8%BF%98%E6%98%AF%E8%BF%9D%E7%BA%A6%22%7D%0A%20%20Q%20--%20%22%E4%BB%98%E6%81%AF%E6%88%90%E6%9C%AC%E4%BD%8E%E4%BA%8E%E6%9C%9F%E6%9D%83%E4%BB%B7%E5%80%BC%22%20--%3E%20KEEP%5B%22%E7%BB%A7%E7%BB%AD%E4%BB%98%E6%81%AF%EF%BC%8C%E4%BF%9D%E4%BD%8F%E7%9C%8B%E6%B6%A8%E6%9C%9F%E6%9D%83%E4%B8%8E%E7%A8%8E%E7%9B%BE%22%5D%0A%20%20Q%20--%20%22%E4%BB%98%E6%81%AF%E6%88%90%E6%9C%AC%E9%AB%98%E4%BA%8E%E6%9C%9F%E6%9D%83%E4%BB%B7%E5%80%BC%22%20--%3E%20DEF%5B%22%E8%BF%9D%E7%BA%A6%EF%BC%9A%E6%8A%8A%E5%85%AC%E5%8F%B8%E4%BA%A4%E7%BB%99%E5%80%BA%E6%9D%83%E4%BA%BA%22%5D%0A%20%20KEEP%20--%3E%20REC%5B%22%E8%8B%A5%20V%20%E5%9B%9E%E5%8D%87%EF%BC%8C%E6%9C%9F%E6%9D%83%E4%BB%B7%E5%80%BC%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20DEF%20--%3E%20LOSS%5B%22%E6%B8%85%E7%AE%97%E6%8D%9F%E8%80%97%EF%BC%8C%E5%80%BA%E6%9D%83%E4%BA%BA%E6%8B%BF%E6%89%A3%E6%8D%9F%E5%90%8E%E7%9A%84%E4%BD%99%E5%80%BC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>宏观课序里的 Kiyotaki–Moore 把抵押边界写进总量；Leland 是单个企业的内生边界。本栏不把信贷周期加总，只把权衡变成可计算的或有要求权。</p><h3 id="不是把公司债当可交易的-black–scholes-产品来做市" tabindex="-1">不是把公司债当可交易的 Black–Scholes 产品来做市 <a class="header-anchor" href="#不是把公司债当可交易的-black–scholes-产品来做市" aria-label="Permalink to &quot;不是把公司债当可交易的 Black–Scholes 产品来做市&quot;">​</a></h3><p>Leland 用 BS 技术，对象是资本结构。信用利差来自违约边界与损耗，不是限价簿上的买卖价差。流动性与展期在后课；本课债是永久、无展期危机。</p><p><span class="marginnote">常见误区：拿 Leland 算出的利差直接对债券市场的信用利差。模型里债是永久的、无流动性折价、无展期风险；真实利差还含流动性补偿与「展期墙」的恐惧，直接对表会把模型误差算大。</span></p><p><span class="marginnote">Leland 1994 还比较保护性条款（资产出售限制等）如何改变 \\(V_B\\) 与债值。契约课再展开 Smith–Warner；这里只要：条款改变期权边界，从而改变最优杠杆。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1994 年模型写成已经解释了调整速度：债务是一次选好的永久票息，没有发行成本下的调整带。下一课动态权衡才加固定调整成本与区间。也不要把 Leland 的利差直接当 WACC 的 \\(r_D\\) 输入而不看边界假设。</p><p>后课默认：权衡可以写成资产扩散上的内生违约；股权是看涨，最优票息与 \\(V_B\\) 联立。再平衡、择时、发行成本尚未进入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Leland：税盾与破产在扩散资产上用或有要求权定价，违约边界内生。</li><li>最优杠杆是期权问题，不是静态的 \\(\\tau_c D\\) 减去一个外生概率。</li><li>永久债、无调整成本；调整带与择时是下一课的缺口。</li><li>出处：Leland, <em>Journal of Finance</em> 1994；对照 Merton, <em>JF</em> 1974。</li></ul>',10))])}const F=s(p,[["render",m]]);export{u as __pageData,F as default};
